package com.mediaforge.app.subs

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/** 17.a2: round trips of every subtitle format and the shared time / colour helpers. */
class FormatsTest {
    private val ass = """
        [Script Info]
        ; Script generated by Aegisub
        Title: Test
        ScriptType: v4.00+
        PlayResX: 1920
        PlayResY: 1080

        [Aegisub Project Garbage]
        Video File: movie.mkv

        [V4+ Styles]
        Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
        Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,2,1,2,10,10,20,1
        Style: Sign,UthmanTN1,60.5,&H0000FFFF,&H000000FF,&H00000000,&H00000000,0,-1,0,0,100,100,0,0,1,3,0,8,10,10,10,178

        [Events]
        Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
        Dialogue: 0,0:00:01.00,0:00:03.50,Default,Ali,0,0,0,,Hello, world, with commas
        Comment: 1,0:00:04.00,0:00:05.00,Sign,,0,0,0,Banner;5,{\an8\b1}مرحبا\Nبالعالم
        Dialogue: 0,1:02:03.45,1:02:04.00,Default,,0,0,0,,{\i1}last{\i0}

        [Fonts]
        fontname: a_0.ttf
        M3=@-M3=@-M3=@-
        M3=@-

    """.trimIndent()

    @Test fun assRoundTrip() {
        val f = AssFormat.parse(ass)
        assertEquals(2, f.styles.size)
        assertEquals(3, f.events.size)
        assertEquals("Hello, world, with commas", f.events[0].text)
        assertEquals("Ali", f.events[0].actor)
        assertTrue(f.events[1].comment)
        assertEquals("{\\an8\\b1}مرحبا\\Nبالعالم", f.events[1].text)
        assertEquals(3723450L, f.events[2].startMs)
        assertEquals(1920, f.playResX)
        assertEquals(1, f.attachments.size)
        assertEquals("a_0.ttf", f.attachments[0].name)
        assertEquals("movie.mkv", f.garbage.first().value)
        val sign = f.style("Sign")!!
        assertEquals("UthmanTN1", sign.fontName)
        assertEquals(60.5f, sign.fontSize, 0.001f)
        assertEquals(8, sign.alignment)
        assertTrue(sign.italic)
        assertEquals(0xFFFFFF00.toInt(), sign.primary)
        assertEquals(0x7F000000, f.style("Default")!!.back) // &H80 alpha = half transparent
        val again = AssFormat.parse(AssFormat.write(f))
        assertEquals(f, again)
    }

    @Test fun ssaLegacyAlignment() {
        val ssa = """
            [Script Info]
            ScriptType: v4.00

            [V4 Styles]
            Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, TertiaryColour, BackColour, Bold, Italic, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, AlphaLevel, Encoding
            Style: Top,Arial,20,16777215,255,0,0,0,0,1,2,2,6,10,10,10,0,0

            [Events]
            Format: Marked, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
            Dialogue: Marked=0,0:00:01.00,0:00:02.00,Top,,0000,0000,0000,,old
        """.trimIndent()
        val f = AssFormat.parse(ssa)
        assertEquals(8, f.style("Top")!!.alignment) // SSA 6 = top centre = numpad 8
        assertEquals("old", f.events.single().text)
    }

    @Test fun srt() {
        val srt = "1\r\n00:00:01,000 --> 00:00:02,500\r\n<i>Hi</i> there\r\nsecond line\r\n\r\n2\r\n00:01:00,100 --> 00:01:01,000\r\n<font color=\"#FF0000\">red</font>\r\n"
        assertTrue(SrtFormat.detect(srt))
        val f = SrtFormat.parse(srt)
        assertEquals(2, f.events.size)
        assertEquals(1000L, f.events[0].startMs)
        assertEquals(2500L, f.events[0].endMs)
        assertEquals("{\\i1}Hi{\\i0} there\\Nsecond line", f.events[0].text)
        val out = SrtFormat.write(f)
        assertTrue(out, out.contains("00:00:01,000 --> 00:00:02,500"))
        assertTrue(out, out.contains("<i>Hi</i> there\nsecond line") || out.contains("<i>Hi</i> there\r\nsecond line"))
        val back = SrtFormat.parse(out)
        assertEquals(f.events.map { it.startMs to it.endMs }, back.events.map { it.startMs to it.endMs })
        assertEquals(f.events.map { it.text }, back.events.map { it.text })
    }

    @Test fun vtt() {
        val vtt = "WEBVTT\n\nNOTE a comment\n\n00:01.000 --> 00:02.000 align:start\n<v Bob>Hello <b>you</b>\n\n01:00:00.000 --> 01:00:01.000\nبعد ساعة\n"
        assertTrue(VttFormat.detect(vtt))
        val f = VttFormat.parse(vtt)
        assertEquals(2, f.events.size)
        assertEquals(1000L, f.events[0].startMs)
        assertEquals("Bob", f.events[0].actor)
        assertEquals(3600000L, f.events[1].startMs)
        val back = VttFormat.parse(VttFormat.write(f))
        assertEquals(f.events.map { it.startMs to it.endMs }, back.events.map { it.startMs to it.endMs })
        assertEquals(f.events.map { it.text }, back.events.map { it.text })
        assertEquals("Bob", back.events[0].actor)
    }

    @Test fun sbv() {
        val sbv = "0:00:01.000,0:00:02.000\nOne\ntwo\n\n0:00:03.500,0:00:04.000\nThree\n"
        val f = SubFormats.detect(null, sbv)!!.parse(sbv)
        assertEquals(2, f.events.size)
        assertEquals("One\\Ntwo", f.events[0].text)
        val back = SbvFormat.parse(SbvFormat.write(f))
        assertEquals(f.events, back.events)
    }

    @Test fun lrc() {
        val lrc = "[ti:Song]\n[ar:Me]\n[00:01.00]First\n[00:03.50][00:10.00]Twice\n[00:05.00]\n"
        assertTrue(LrcFormat.detect(lrc))
        val f = LrcFormat.parse(lrc)
        val texts = f.events.filter { !it.comment }.map { it.text }
        assertTrue(texts.toString(), texts.containsAll(listOf("First", "Twice")))
        val first = f.events.first { it.text == "First" }
        assertEquals(1000L, first.startMs)
        assertEquals(3500L, first.endMs)
        val twice = f.events.filter { it.text == "Twice" }
        assertEquals(2, twice.size)
        assertEquals(5000L, twice.minByOrNull { it.startMs }!!.endMs) // the empty stamp ends it
        val back = LrcFormat.parse(LrcFormat.write(f))
        assertEquals(f.events.filter { it.text.isNotEmpty() }.map { it.startMs to it.text }.sortedBy { it.first },
            back.events.filter { it.text.isNotEmpty() }.map { it.startMs to it.text }.sortedBy { it.first })
    }

    @Test fun microDvd() {
        val sub = "{1}{1}25\n{25}{50}{y:i}Hello|world\n{75}{100}Bye\n"
        val f = MicroDvdFormat.parse(sub)
        assertEquals(2, f.events.size)
        assertEquals(1000L, f.events[0].startMs)
        assertEquals(2000L, f.events[0].endMs)
        assertTrue(f.events[0].text, f.events[0].text.contains("Hello\\Nworld"))
        val back = MicroDvdFormat.parse(MicroDvdFormat.write(f))
        assertEquals(f.events.map { it.startMs to it.endMs }, back.events.map { it.startMs to it.endMs })
        assertEquals(f.events.map { it.text }, back.events.map { it.text })
    }

    @Test fun ttml() {
        val ttml = """<?xml version="1.0" encoding="UTF-8"?>
<tt xmlns="http://www.w3.org/ns/ttml"><body><div>
<p begin="00:00:01.000" end="00:00:02.000">Hello<br/>there</p>
<p begin="3s" dur="1.5s">Next &amp; last</p>
</div></body></tt>"""
        assertTrue(TtmlFormat.detect(ttml))
        val f = TtmlFormat.parse(ttml)
        assertEquals(2, f.events.size)
        assertEquals("Hello\\Nthere", f.events[0].text)
        assertEquals(3000L, f.events[1].startMs)
        assertEquals(4500L, f.events[1].endMs)
        assertEquals("Next & last", f.events[1].text)
        val back = TtmlFormat.parse(TtmlFormat.write(f))
        assertEquals(f.events.map { it.startMs to it.endMs }, back.events.map { it.startMs to it.endMs })
        assertEquals(f.events.map { it.text }, back.events.map { it.text })
    }

    @Test fun txt() {
        val f = TxtFormat.parse("# note\nline one\n\nline two\n")
        assertEquals(3, f.events.size)
        assertTrue(f.events[0].comment)
        assertEquals("line two", f.events[2].text)
        assertEquals("# note\nline one\nline two\n", TxtFormat.write(f))
    }

    @Test fun everyFormatSurvivesAssModel() {
        val base = AssFormat.parse(ass).let { it.copy(events = it.events.filter { e -> !e.comment }) }
        for (fmt in SubFormats.all) {
            if (fmt == TxtFormat) continue
            val back = fmt.parse(fmt.write(base))
            assertEquals(fmt.id, base.events.size, back.events.size)
            for ((a, b) in base.events.zip(back.events)) {
                // MicroDVD stores frames: allow one frame of rounding
                assertTrue("${fmt.id} start ${a.startMs} vs ${b.startMs}", kotlin.math.abs(a.startMs - b.startMs) <= 42)
                assertTrue("${fmt.id} end ${a.endMs} vs ${b.endMs}", kotlin.math.abs(a.endMs - b.endMs) <= 42)
                assertEquals(fmt.id, AssLook.plainText(a.text).replace("\\N", "\n"), AssLook.plainText(b.text).replace("\\N", "\n"))
            }
        }
    }

    @Test fun detectByNameThenContent() {
        assertEquals("srt", SubFormats.detect("a.SRT", "")!!.id)
        assertEquals("ass", SubFormats.detect("a.ssa", "")!!.id)
        assertEquals("ass", SubFormats.detect(null, ass)!!.id)
        assertEquals("vtt", SubFormats.detect(null, "WEBVTT\n")!!.id)
        assertNotNull(SubFormats.byId("txt"))
    }

    @Test fun timesAndColours() {
        assertEquals(3723450L, parseAssTime("1:02:03.45"))
        assertEquals(1500L, parseAssTime("0:00:01.5"))
        assertEquals(1234L, parseAssTime("0:00:01.234"))
        assertEquals("1:02:03.45", formatAssTime(3723450L))
        assertEquals("0:00:00.01", formatAssTime(5L)) // centisecond rounding
        assertEquals(0xFF112233.toInt(), parseAssColor("&H00332211"))
        assertEquals(0xFF112233.toInt(), parseAssColor("&H332211&"))
        assertEquals("&H00332211", formatAssColor(0xFF112233.toInt()))
        assertEquals(65000L, parseClock("01:05"))
        assertEquals(3_600_000L + 1L, parseClock("1:00:00.001"))
        assertEquals("01:00:00.001", formatClock(3_600_001L))
        assertFalse(parseAssTime("abc") != null)
    }
}
